```bash
cat <<'EOF' > test_padding.go
package main

import (
	"fmt"
)

const StorePageSize = 4096

func pageAlignCeil(pos int64) int64 {
	rem := pos % int64(StorePageSize)
	if rem != 0 {
		return pos + int64(StorePageSize) - rem
	}
	return pos
}

func main() {
	// Test cases
	testCases := []struct {
		footerPos     int64
		footerWritten int
	}{
		{4096, 100},   // Footer starts at page boundary
		{4100, 100},   // Footer starts after page boundary
		{8192, 2000},  // Footer starts at another page boundary
		{8200, 3000},  // Footer starts after page boundary
	}

	for _, tc := range testCases {
		// Old (incorrect) calculation
		oldPadding := int(pageAlignCeil(int64(tc.footerWritten))) - tc.footerWritten

		// New (correct) calculation
		newPadding := int(pageAlignCeil(tc.footerPos+int64(tc.footerWritten))) - (tc.footerPos + int64(tc.footerWritten))

		fmt.Printf("FooterPos: %d, FooterWritten: %d\n", tc.footerPos, tc.footerWritten)
		fmt.Printf("  Old padding: %d\n", oldPadding)
		fmt.Printf("  New padding: %d\n", newPadding)
		fmt.Printf("  Next page boundary: %d\n", pageAlignCeil(tc.footerPos+int64(tc.footerWritten)))
		fmt.Println()
	}
}
EOF
```

